document.addEventListener("DOMContentLoaded", () => {
  const video = document.getElementById("bgVideo");
  const jackpotList = document.getElementById("jackpotList");
  const reviewList = document.getElementById("reviewList");
  const reviewInput = document.getElementById("reviewInput");
  const reviewSubmit = document.getElementById("reviewSubmit");
  const reviewThanks = document.getElementById("reviewThanks");
  const reviewPicked = document.getElementById("reviewPicked");
  const reviewStars = Array.from(document.querySelectorAll(".review-star"));
  const flagImages = Array.from(document.querySelectorAll(".flag-circle[data-flag-key]"));

  const encodedFlagUrls = {
    my: "data:image/png;base64,",
    uk: "data:image/png;base64,",
    fr: "data:image/png;base64,",
    de: "data:image/png;base64,",
    it: "data:image/png;base64,",
    es: "data:image/png;base64,",
    pt: "data:image/png;base64,",
    ru: "data:image/png;base64,"
  };

  const providers = ["CQ9", "PG Soft", "JILI", "Red Tiger", "Microgaming", "Pragmatic Play", "Habanero"];
  const games = [
    "Spade Fishing",
    "Gem Saviour",
    "Dragon",
    "Immortal Romance",
    "Pirates' Plenty",
    "Fortune Gems",
    "Esqueleto Explosivo",
    "Lucky Neko",
    "Wild Ape"
  ];
  const userHeads = ["q", "p", "k", "d", "y", "m", "n", "h", "r", "s", "t", "x", "z"];
  const reviewNames = ["001", "008", "117", "193", "226", "275", "322", "451", "598", "721", "888"];
  const reviewTemplates = [
    { rating: 5, text: "Cổng chính thức, vào mượt và ổn định." },
    { rating: 5, text: "Rút tiền nhanh, thao tác đơn giản, rất yên tâm." },
    { rating: 5, text: "Tốc độ tải tốt, không bị giật khi truy cập." },
    { rating: 4, text: "Hỗ trợ nhanh, trả lời rõ ràng, khá ổn." },
    { rating: 4, text: "Hỗ trợ phản hồi nhanh, xử lý vấn đề tốt." },
    { rating: 4, text: "Vào game ổn, chăm sóc khách hàng nhanh." },
    { rating: 5, text: "Link vào ổn định cả giờ cao điểm." },
    { rating: 5, text: "Giao diện dễ dùng, nhìn rõ và không rối." },
    { rating: 5, text: "Bảo mật tốt, đăng nhập nhanh và an toàn." },
    { rating: 5, text: "Không bị chặn lặt vặt, vào game rất ổn." }
  ];
  const reviewStorageKey = "xx88_user_reviews";
  const userReviews = [];
  let selectedRating = 5;
  let reviewThanksTimer;

  // Chặn chuột phải + F12 / DevTools shortcuts (KHÔNG redirect)
  function initSourceGuard() {
    document.addEventListener("contextmenu", (event) => {
      event.preventDefault();
    });

    document.addEventListener("keydown", (event) => {
      const key = event.key.toLowerCase();
      const ctrlShift = event.ctrlKey && event.shiftKey;
      const blocked =
        event.key === "F12" ||
        (ctrlShift && (key === "i" || key === "j" || key === "c")) ||
        (event.ctrlKey && (key === "u" || key === "s"));

      if (blocked) {
        event.preventDefault();
      }
    });
  }

  function initFlagImages() {
    flagImages.forEach((image) => {
      const key = image.dataset.flagKey;
      const dataUri = encodedFlagUrls[key];
      if (!dataUri) return;
      image.src = dataUri;
    });
  }

  if (video) {
    video.muted = true;
    video.play().catch(() => {
      console.log("Video autoplay bi chan boi trinh duyet.");
    });
  }

  initSourceGuard();
  initFlagImages();

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function randomFrom(list) {
    return list[randomInt(0, list.length - 1)];
  }

  function randomTime() {
    const style = randomInt(1, 3);
    if (style === 1) return `${randomInt(6, 58)}p`;
    if (style === 2) return `${randomInt(1, 12)}g`;
    return `${randomInt(1, 12)}g${randomInt(1, 59)}`;
  }

  function randomUser() {
    return `${randomFrom(userHeads)}***${randomInt(1, 9)}`;
  }

  function randomAmount() {
    const amount = randomInt(45, 980) + randomInt(0, 9) / 10;
    return `${amount.toFixed(1)}M`;
  }

  function randomJackpotItem() {
    return {
      time: randomTime(),
      game: `${randomFrom(providers)} - ${randomFrom(games)}`,
      user: randomUser(),
      amount: randomAmount()
    };
  }

  function randomReviewTime() {
    const style = randomInt(1, 4);
    if (style === 1) return `${randomInt(2, 59)} phút trước`;
    if (style === 2) return `${randomInt(1, 23)} giờ trước`;
    if (style === 3) return `${randomInt(1, 6)} ngày trước`;
    return `${String(randomInt(1, 28)).padStart(2, "0")}/${String(randomInt(1, 12)).padStart(2, "0")}/2026`;
  }

  function randomReviewItem() {
    const template = randomFrom(reviewTemplates);
    return {
      name: `Ẩn danh ${randomFrom(reviewNames)}`,
      time: randomReviewTime(),
      rating: template.rating,
      text: template.text
    };
  }

  function saveUserReviews() {
    try {
      localStorage.setItem(reviewStorageKey, JSON.stringify(userReviews));
    } catch (error) {
      console.log("Khong the luu danh gia vao localStorage.", error);
    }
  }

  function loadUserReviews() {
    try {
      const raw = localStorage.getItem(reviewStorageKey);
      if (!raw) return;
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return;
      parsed
        .filter(
          (item) =>
            item &&
            typeof item.name === "string" &&
            typeof item.time === "string" &&
            typeof item.text === "string" &&
            typeof item.rating === "number"
        )
        .slice(0, 6)
        .forEach((item) => userReviews.push(item));
    } catch (error) {
      console.log("Khong the doc danh gia tu localStorage.", error);
    }
  }

  function buildRateStars(rating) {
    const safeRating = Math.max(1, Math.min(5, rating));
    return `${"★".repeat(safeRating)}${"☆".repeat(5 - safeRating)}`;
  }

  function composeReviewRows() {
    const rows = [];
    const usedSignatures = new Set();

    userReviews.forEach((item) => {
      if (rows.length >= 3) return;
      const signature = `${item.rating}|${item.text}|${item.name}`;
      if (!usedSignatures.has(signature)) {
        usedSignatures.add(signature);
        rows.push(item);
      }
    });

    let attempts = 0;
    while (rows.length < 3 && attempts < 80) {
      const candidate = randomReviewItem();
      const signature = `${candidate.rating}|${candidate.text}`;
      attempts += 1;
      if (usedSignatures.has(signature)) continue;
      usedSignatures.add(signature);
      rows.push(candidate);
    }

    while (rows.length < 3) {
      rows.push({
        name: `Ẩn danh ${randomFrom(reviewNames)}`,
        time: randomReviewTime(),
        rating: 5,
        text: `Đánh giá ngẫu nhiên #${randomInt(100, 999)}`
      });
    }

    return rows;
  }

  function applyReviewToCard(card, data) {
    const nameEl = card.querySelector(".review-name");
    const timeEl = card.querySelector(".review-time");
    const rateEl = card.querySelector(".review-rate");
    const textEl = card.querySelector(".review-text");

    if (nameEl) nameEl.textContent = data.name;
    if (timeEl) timeEl.textContent = data.time;
    if (rateEl) rateEl.textContent = buildRateStars(data.rating || 5);
    if (textEl) textEl.textContent = data.text;
  }

  function ensureReviewCards(count) {
    if (!reviewList) return [];

    let cards = Array.from(reviewList.querySelectorAll(".review-card"));
    if (cards.length === count) return cards;

    reviewList.innerHTML = "";
    for (let i = 0; i < count; i += 1) {
      const card = document.createElement("article");
      card.className = "review-card";
      card.innerHTML = `
        <div class="review-card-head">
          <span class="review-avatar">👤</span>
          <div>
            <p class="review-name"></p>
            <p class="review-time"></p>
          </div>
        </div>
        <p class="review-rate">★★★★★</p>
        <p class="review-text"></p>
      `;
      reviewList.appendChild(card);
    }

    return Array.from(reviewList.querySelectorAll(".review-card"));
  }

  function renderJackpotRows() {
    if (!jackpotList) return;

    const rows = [randomJackpotItem(), randomJackpotItem(), randomJackpotItem()];
    jackpotList.innerHTML = rows
      .map(
        (row) => `
          <div class="jackpot-row is-updating">
            <span class="jackpot-time">${row.time}</span>
            <span class="jackpot-game">${row.game}</span>
            <span class="jackpot-user">${row.user}</span>
            <span class="jackpot-amount">${row.amount}</span>
          </div>
        `
      )
      .join("");

    setTimeout(() => {
      jackpotList.querySelectorAll(".jackpot-row").forEach((row) => {
        row.classList.remove("is-updating");
      });
    }, 450);
  }

  function renderReviewCards() {
    if (!reviewList) return;
    const dataRows = composeReviewRows();
    const cards = ensureReviewCards(dataRows.length);
    cards.forEach((card, index) => {
      applyReviewToCard(card, dataRows[index]);
    });
  }

  function showReviewThanks() {
    if (!reviewThanks) return;
    reviewThanks.classList.add("show");
    clearTimeout(reviewThanksTimer);
    reviewThanksTimer = setTimeout(() => {
      reviewThanks.classList.remove("show");
    }, 2200);
  }

  function submitUserReview() {
    if (!reviewInput) return;
    const content = reviewInput.value.trim();
    if (!content) return;

    userReviews.unshift({
      name: `Ẩn danh ${randomFrom(reviewNames)}`,
      time: "Vừa xong",
      rating: selectedRating,
      text: content
    });
    if (userReviews.length > 6) userReviews.length = 6;
    saveUserReviews();

    reviewInput.value = "";
    renderReviewCards();
    showReviewThanks();
  }

  function setSelectedRating(value) {
    selectedRating = value;
    reviewStars.forEach((star) => {
      const starValue = Number(star.dataset.value);
      star.classList.toggle("is-active", starValue <= selectedRating);
    });
    if (reviewPicked) {
      reviewPicked.textContent = `Bạn đang chọn ${selectedRating} sao`;
    }
  }

  if (jackpotList) {
    renderJackpotRows();
    setInterval(renderJackpotRows, 3000);
  }

  loadUserReviews();

  if (reviewList) {
    renderReviewCards();
    setInterval(renderReviewCards, 3000);
  }

  if (reviewSubmit) {
    reviewSubmit.addEventListener("click", submitUserReview);
  }

  if (reviewInput) {
    reviewInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        submitUserReview();
      }
    });
  }

  if (reviewStars.length > 0) {
    reviewStars.forEach((star) => {
      star.addEventListener("click", () => {
        const starValue = Number(star.dataset.value);
        if (!Number.isNaN(starValue)) {
          setSelectedRating(starValue);
        }
      });
    });
    setSelectedRating(selectedRating);
  }
});